import './About.css';
import dasgterIcon from '../assets/dagster-reversed-vertical.jpg';
import dbtIcon from '../assets/dbt-logo.svg';

const About = () => {
  const techCategories = [
    {
      category: 'Backend',
      techs: [
        { name: 'Node.js', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/nodejs/nodejs-original-wordmark.svg", experience: 90 },
        { name: 'NestJS', icon: "https://nestjs.com/img/logo-small.svg", experience: 85 },
        { name: 'Express', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/express/express-original-wordmark.svg", experience: 85 },
        { name: 'TypeScript', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/typescript/typescript-original.svg", experience: 80 },
      ]
    },
    {
      category: 'Data Engineering',
      techs: [
        { name: 'Python', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/python/python-original-wordmark.svg", experience: 80 },
        { name: 'Dagster', icon: dasgterIcon, experience: 75 },
        { name: 'Data Build Tool', icon: dbtIcon, experience: 90 },
        { name: 'SQL', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/mysql/mysql-original-wordmark.svg", experience: 90 },
      ]
    },
    {
      category: 'Databases',
      techs: [
        { name: 'PostgreSQL', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/postgresql/postgresql-original-wordmark.svg", experience: 90 },
        { name: 'MongoDB', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/mongodb/mongodb-original-wordmark.svg", experience: 80 },
        { name: 'DynamoDB', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/dynamodb/dynamodb-original.svg", experience: 50 },
      ]
    },
    {
      category: 'Cloud & DevOps',
      techs: [
        { name: 'AWS', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/amazonwebservices/amazonwebservices-original-wordmark.svg", experience: 65 },
        { name: 'Docker', icon: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/docker/docker-original-wordmark.svg", experience: 70 },
      ]
    }
  ];

  return (
    <section id="about" className="about">
      <h2>About</h2>
      <div className="about-content">
        <p>
          Backend Developer with 4+ years of experience and 1+ year as a Data Engineer, building scalable 
          backend systems, RESTful APIs, and high-volume data pipelines across multiple industries. Proficient in 
          Node.js, NestJS, Python, AWS, Docker, and SQL, with expertise in database optimization, data modeling, 
          ETL processes, and cloud-based solutions. Committed to building secure, scalable, and maintainable 
          software through clean code and collaborative development practices.
        </p>

        <button className="tech-stack-btn">Technology Stack</button>

        {techCategories.map((cat, catIndex) => (
          <div key={catIndex} className="tech-category">
            <h3 className="tech-category-title">{cat.category}</h3>
            <div className="tech-grid">
              {cat.techs.map((tech, index) => (
                <div key={index} className="tech-item" title={`${tech.experience}% Proficiency`}>
                  <span className="tech-icon">
                    <img src={tech.icon} alt={tech.name} />
                  </span>
                  <span className="tech-name">{tech.name}</span>
                  <div className="experience-bar">
                    <div 
                      className="experience-fill" 
                      style={{ width: `${tech.experience}%` }}
                    ></div>
                  </div>
                  <span className="experience-level">{tech.experience}%</span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default About;
